import { PHOTO_BLUR } from "./blur-map.generated";

/**
 * The blurred preview of a photograph as a CSS `url()` value, or `undefined`
 * when the build generated none (an external or unknown file). Issue 236: the
 * surface lays it beneath the real image, so a client navigation shows the
 * motif at once while the file loads. The data URI is generated by
 * `scripts/generate-photo-blur.ts` from files we ship — base64 only, nothing
 * that can close the declaration.
 */
export function photoBlur(src: string): string | undefined {
  const entry = PHOTO_BLUR[src];
  return entry ? `url("${entry.uri}")` : undefined;
}
